Real CastleBehavior::getCampDiameter(const Player *player)
{
	if (!player)
		return 0.0f;

	const CastleBehaviorModuleData *data = (const CastleBehaviorModuleData *)getModuleData();
	int count = data->m_factionDecal.size();
	for (int i = 0; i < count; ++i)
	{
		CastleFactionDecal record = data->m_factionDecal[i];
		if (record.m_factionName.compare(player->m_side) == 0)
			return record.m_value;
	}
	return 0.0f;
}

